import{_ as t,o,c as r,ag as d}from"./chunks/framework.Dk8PTAaz.js";const p=JSON.parse('{"title":"与 vue-router 的差异","description":"","frontmatter":{},"headers":[],"relativePath":"guide/differences.md","filePath":"guide/differences.md","lastUpdated":1788608281000}'),a={name:"guide/differences.md"};function c(u,e,s,n,i,l){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="与-vue-router-的差异" tabindex="-1">与 vue-router 的差异 <a class="header-anchor" href="#与-vue-router-的差异" aria-label="Permalink to &quot;与 vue-router 的差异&quot;">​</a></h1><p>unix-router 在 API 风格上对齐 vue-router 4，但由于 uni-app x 采用<strong>静态 pages.json 页面模型</strong>，二者存在本质差异。本文说明哪些能力<strong>等价实现</strong>、哪些<strong>不适配</strong>。</p><h2 id="能力对照" tabindex="-1">能力对照 <a class="header-anchor" href="#能力对照" aria-label="Permalink to &quot;能力对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>vue-router 4</th><th>unix-router（uni-app x）</th></tr></thead><tbody><tr><td><code>createRouter({ history })</code></td><td><code>createRouter({ routes })</code>，无需 <code>history</code>（由原生页面栈承担）</td></tr><tr><td>路径/命名/参数/查询匹配</td><td>✅ 支持</td></tr><tr><td><code>route.params / query / meta / fullPath</code></td><td>✅ 支持（params 经查询编码跨页传递）</td></tr><tr><td><code>currentRoute</code> 响应式</td><td>✅ 支持</td></tr><tr><td>push / replace / back</td><td>✅ 支持（+ <code>relaunch</code>）</td></tr><tr><td><code>router.go(n)</code></td><td>⚠️ 语义受限：退化用 <code>back(delta)</code></td></tr><tr><td>beforeEach / beforeResolve / afterEach</td><td>✅ 支持</td></tr><tr><td>beforeEnter / onBeforeRouteLeave</td><td>✅ 支持</td></tr><tr><td><code>useRouter / useRoute / useLink</code></td><td>✅ 支持</td></tr><tr><td>错误体系 NavigationFailure</td><td>✅ 支持</td></tr><tr><td><code>isReady / onError</code></td><td>✅ 支持（+ <code>onRouteChange</code>）</td></tr><tr><td><strong>动态路由</strong> <code>addRoute / removeRoute</code></td><td>❌ 不支持（编译期忽略未注册页）</td></tr><tr><td><strong>嵌套路由</strong> <code>children</code></td><td>❌ 不支持（扁平页面模型）</td></tr><tr><td><strong>命名视图 / RouterView</strong></td><td>❌ 不支持（无页内渲染占位）</td></tr><tr><td><strong>scrollBehavior</strong></td><td>❌ 不支持（滚动由 uni-app 原生管理）</td></tr><tr><td>hash 路由模式</td><td>❌ 不支持（无 URL 概念）</td></tr></tbody></table><h2 id="关键差异说明" tabindex="-1">关键差异说明 <a class="header-anchor" href="#关键差异说明" aria-label="Permalink to &quot;关键差异说明&quot;">​</a></h2><h3 id="_1-没有-url-history" tabindex="-1">1. 没有 URL / history <a class="header-anchor" href="#_1-没有-url-history" aria-label="Permalink to &quot;1. 没有 URL / history&quot;">​</a></h3><p>uni-app x 无浏览器 URL；&quot;历史&quot;由原生页面栈（<code>getCurrentPages</code>）承担。因此：</p><ul><li>无 <code>createWebHistory</code> / <code>createWebHashHistory</code> / <code>createMemoryHistory</code>。</li><li>无 hash 参数；滚动行为由原生管理。</li></ul><h3 id="_2-静态路由表" tabindex="-1">2. 静态路由表 <a class="header-anchor" href="#_2-静态路由表" aria-label="Permalink to &quot;2. 静态路由表&quot;">​</a></h3><p>页面必须先在 <code>pages.json</code> 注册，运行时 <code>addRoute</code> 无法把页面编译进包 → 不支持动态路由。 分包（<code>subPackages</code>）可作资源上的&quot;懒加载&quot;，但不是 vue-router 的嵌套/动态语义。</p><h3 id="_3-params-的实现" tabindex="-1">3. params 的实现 <a class="header-anchor" href="#_3-params-的实现" aria-label="Permalink to &quot;3. params 的实现&quot;">​</a></h3><p>原生不支持路径参数（路径即页面路径）。unix-router 将 <code>params</code> 经<strong>查询编码</strong> （<code>__unixr_p_</code> 保留前缀）在页面 URL 间传递，目标页 <code>route.params</code> 可读取。因此：</p><ul><li>params 形如 <code>Map&lt;string,string&gt;</code>（字符串值）。</li><li>params 会以编码形式出现在 URL 查询中（不暴露明文键名）。</li></ul><h3 id="_4-go-n" tabindex="-1">4. <code>go(n)</code> <a class="header-anchor" href="#_4-go-n" aria-label="Permalink to &quot;4. `go(n)`&quot;">​</a></h3><p>vue-router 的 <code>go</code> 基于 history 相对跳转，uni-app x 无该栈 API → 用 <code>back(delta)</code> 代替。</p><h3 id="_5-组件内守卫" tabindex="-1">5. 组件内守卫 <a class="header-anchor" href="#_5-组件内守卫" aria-label="Permalink to &quot;5. 组件内守卫&quot;">​</a></h3><p>uni-app x 页面每次导航创建新实例（无 keep-alive），故 <code>onBeforeRouteUpdate</code> 极少触发、 <code>onBeforeRouteEnter</code> 效果有限，<code>onBeforeRouteLeave</code> 最常用。</p><h2 id="迁移心智" tabindex="-1">迁移心智 <a class="header-anchor" href="#迁移心智" aria-label="Permalink to &quot;迁移心智&quot;">​</a></h2><p>如果你来自 vue-router，多数代码可直接迁移：<code>createRouter</code>、守卫、<code>useRouter/useRoute/useLink</code>、<code>push/replace/back</code> 用法一致；仅需注意将 <code>components</code> 配置改为 <code>pages.json</code> 注册，并放弃动态路由 / 嵌套 / 命名视图。</p>',19)])])}const g=t(a,[["render",c]]);export{p as __pageData,g as default};
